    if (v.status !== 'Published') { box.innerHTML = N.empty('This vacancy is no longer open', '', 'briefcase'); return; }
    box.innerHTML = `<div class="grid g-2-1"><div><span class="eyebrow">${esc(v.department)} · ${esc(v.ref)}</span><h1>${esc(v.title)}</h1><p class="muted">${esc(N.db.getKey('orgSettings', {}).name)} · ${esc(ves ? ves.type + ' · ' + ves.flag + ' flag' : 'Fleet-wide')}</p><p style="font-size:16px">${esc(v.description)}</p><h3 class="mt-3">Requirements</h3><ul class="ticks"><li>Rank: ${esc(v.rank)}</li><li>Certificates: ${esc(v.requiredCerts)}</li><li>Experience: ${esc(v.experience)}</li><li>Contract: ${esc(v.duration)}</li></ul></div><div><div class="card"><div class="card-body">${N.dl([['Joining date', N.fmt.date(v.joiningDate)], ['Apply by', N.fmt.date(v.deadline)], ['Salary', v.salaryMin ? N.fmt.money(v.salaryMin, 'USD') + ' – ' + N.fmt.money(v.salaryMax) + ' / month' : 'Competitive'], ['Positions', v.positions]])}<button class="btn btn-primary btn-lg w-100 mt-2" data-apply>${N.ico('send')}Apply now</button><p class="small muted mt-2 mb-0">Already have a Nyocrew seafarer account? <a href="${N.url(P('authentication/login'))}">Sign in</a> to apply with your saved profile and track your application.</p></div></div></div></div>`;
    N.$('[data-apply]', box).onclick = () => N.formModal({ title: 'Apply — ' + v.title, intro: 'Applying does not create an employment relationship. You can track your application status by email or in the seafarer portal.', fields: [{ k: 'candidate', label: 'Full name', req: true }, { k: 'email', label: 'Email', type: 'email', req: true }, { k: 'phone', label: 'Phone', type: 'tel', req: true }, { k: 'nationality', label: 'Nationality', type: 'select', req: true, options: () => N.ref('nationalities') }, { k: 'experience', label: 'Years in rank', req: true }, { k: 'cv', label: 'CV', type: 'file', req: true, accept: '.pdf,.doc,.docx' }, { k: 'certificates', label: 'Certificates', type: 'file', multiple: true }, { k: 'consent', label: 'Consent', type: 'checkbox', text: 'I consent to my data being processed for this application in line with the Privacy Policy.', req: true }], saveLabel: 'Submit application', onSave: (x) => { const a = N.db.save('applications', { ...x, ref: N.db.nextRef('APP', 'applications'), vacancyId: v.id, rank: v.rank, status: 'Submitted', appliedOn: new Date().toISOString(), reviews: [], approvals: [], history: [{ status: 'Submitted', ts: new Date().toISOString(), user: x.candidate }] }); N.notify('New application received', `${x.candidate} applied for ${v.title}`, { icon: 'file-user', link: P('recruitment/evaluation') + '?id=' + a.id }); N.modal({ title: 'Application submitted', body: `<div class="text-center"><div class="confirm-ico info">${N.ico('check')}</div><h3>Thank you, ${esc(x.candidate.split(' ')[0])}!</h3><p>Your application reference is <b>${esc(a.ref)}</b>. Status: ${N.badge('Submitted')}</p><p class="muted">We'll email ${esc(x.email)} as your application progresses.</p></div>` }); } });
